import sys

def min_product(a, b, x, y, n):
    def can_reduce(k):
        return (a - k >= x) and (b - (n - k) >= y)

    low, high = 0, min(a - x, b - y, n)
    while low < high:
        mid = (low + high) // 2
        if can_reduce(mid):
            high = mid
        else:
            low = mid + 1

    return max(x, a - low) * max(y, b - (n - low))

